/* The new-career draft owns its rules; editing setup never changes the active save. */
function setupLeagueRules(d=setupDraft){return readLeagueSettings({...LEAGUE_SETTING_DEFAULTS,...d.leagueSettings},{year:d.year,teams:d.teams,leagueGender:d.leagueGender})}
function syncSetupScheduleDefaults(d=setupDraft){if(d.meetings==='custom')return;syncAlignment(d);d.leagueSettings??={...LEAGUE_SETTING_DEFAULTS};if(d.meetings===82){Object.assign(d.leagueSettings,{seasonGames:82,divisionGames:16,conferenceGames:36,seasonStart:'10-28',seasonEnd:new Date(Date.UTC(d.year,9,28+173+(d.leagueSettings.allStarEnabled?(d.leagueSettings.allStarSchedule==='custom'?(d.leagueSettings.allStarEventDays||3):((d.leagueSettings.allStarEventDays||3)-3)):0))).toISOString().slice(5,10)})}else{const calendar=schedule(d.meetings,d.teams.length);if(d.leagueSettings.allStarEnabled)calendar.push(...Array.from({length:d.leagueSettings.allStarEventDays||3},()=>[]));Object.assign(d.leagueSettings,calendarSettingDefaults({year:d.year,teams:d.teams,schedule:calendar}))}}
function validateSetupLeagueSettings(d){const rules=setupLeagueRules(d),aligned=copy(d);syncAlignment(aligned);validatePlayoffRules(rules,aligned.teams);if(d.meetings===4&&d.teams.length>30)throw Error('Expanded leagues support one or two games per opponent, or a custom schedule.');if(d.meetings==='custom')customSeasonSchedule(aligned.teams,d.year,rules,d.leagueGender);return rules}
function setupPageNavigation(){return `<nav class="setup-page-navigation" aria-label="New career pages"><button type="button" aria-current="${setupPage==='career'?'step':'false'}" onclick="goSetupPage('career')">1 · Career &amp; team</button><button type="button" aria-current="${setupPage==='settings'?'step':'false'}" onclick="goSetupPage('settings')">2 · League settings</button></nav>`}
function goSetupPage(page){if(!['career','settings'].includes(page))return;captureSetup();setupPage=page;if(page==='settings'&&setupDraft.meetings!=='custom')syncSetupScheduleDefaults();renderSetup();window.scrollTo(0,0)}
function changeSetupScheduleFormat(){captureSetup();syncSetupScheduleDefaults();renderSetup()}
function captureSetupRules(){captureSetup();const f=document.getElementById('career-form');if(f?.elements?.meetings)f.elements.meetings.value=String(setupDraft.meetings)}
function renderSetupLeagueSettings(){const d=setupDraft;syncAlignment(d);applyLeagueTheme();const rules={...LEAGUE_SETTING_DEFAULTS,...d.leagueSettings};document.getElementById('app').innerHTML=`<main class="setup-page"><header class="setup-top"><button type="button" onclick="goSetupPage('career')">← Career &amp; team</button><span>HOOPS DYNASTY</span><small>THE BLUEPRINT</small></header><div class="setup-wrap"><div class="setup-heading"><div><div class="eyebrow">NEW CAREER · ${d.year}</div><h1>LEAGUE SETTINGS</h1><p>${escapeHTML(d.leagueName)} · ${d.teams.length} teams</p></div><div class="actions"><button type="button" onclick="openPresets()">Presets</button><button type="button" onclick="openLeagueManager()">Manage league</button></div></div>${setupPageNavigation()}<form id="career-form" onsubmit="submitCareer(event)"><section class="setup-section"><h2>League basics</h2><div class="setup-fields"><label>Player gender<select name="leagueGender" onchange="captureSetup()">${genderOptions(d.leagueGender||'male')}</select></label><label>Season format<select name="meetings" onchange="changeSetupScheduleFormat()"><option value="custom" ${d.meetings==='custom'?'selected':''}>Custom · Schedule settings below</option><option value="82" ${d.meetings===82?'selected':''}>82 games · NBA-style</option>${[1,2,4].map(n=>`<option value="${n}" ${d.meetings===n?'selected':''}>${(d.teams.length-1)*n} games · ${n} per opponent</option>`).join('')}</select></label><label class="dark-mode-row"><span>Dark mode<small>Apply to setup and your career</small></span><input type="checkbox" name="darkMode" role="switch" ${d.darkMode?'checked':''} onchange="captureSetup();applyLeagueTheme()"></label></div></section><div class="setup-league-rules" oninput="captureSetupRules()" onchange="captureSetupRules()">${leagueSettingsMarkup(rules,d.year,()=> '',LEAGUE_SETTING_GROUPS,d.cap)}</div><p class="setup-help">Settings apply when you start this career. Schedule and playoff rules lock after the first regular-season game.</p><div class="setup-bottom"><button type="button" onclick="goSetupPage('career')">← Back to career &amp; team</button><button type="submit" class="setup-start" ${saveActionBusy?'disabled':''}>START CAREER →</button></div></form></div></main>`}

function buildSetupCareer(draft){const d=copy(draft);if(d.leagueSettings?.historicalSource==='wnba'){const r=wnbaRules(d.year,{year:d.year});Object.assign(d.leagueSettings,wnbaSettings(r));d.cap=r.cap/1e6;}syncAlignment(d);const chosen=d.teams.findIndex(t=>t.key===d.selectedKey);if(chosen>0)d.teams.unshift(d.teams.splice(chosen,1)[0]);const financial=d.leagueSettings?.historicalSource==='wnba'?{year:d.year,leagueSettings:d.leagueSettings}:null;const nextState=fresh(d.teams,d.meetings==='custom'?1:d.meetings,d.year,d.leagueGender||'male',setupLeagueRules(d).rosterMin,financial);nextState.leagueSettings=setupLeagueRules(d);if(d.meetings==='custom'){nextState.schedule=customSeasonSchedule(nextState.teams,d.year,nextState.leagueSettings);nextState.scheduleFormat='custom';nextState.meetings=nextState.leagueSettings.seasonGames;nextState.customScheduleAlignment=managementAlignment(nextState.teams)}else Object.assign(nextState.leagueSettings,calendarSettingDefaults(nextState));Object.assign(nextState,{year:d.year,leagueName:d.leagueName.trim(),gmName:d.gmName.trim(),salaryCap:d.cap,darkMode:d.darkMode,conferences:d.conferences,divisions:d.divisions});const contractRules=nextState.leagueSettings;if(financial){wnbaInitialize(nextState);}else for(const t of nextState.teams)for(const p of t.roster){p.salary=Math.max(contractRules.minContract,Math.min(contractRules.maxContract,contractRules.historicalSource!=='custom'?Math.round(p.salary*d.cap/150*1e6)/1e6:p.salary));p.contractThrough=d.year+contractRules.minContractYears-1;}if(!financial&&contractRules.historicalSource!=='custom'){for(const p of nextState.free)p.salary=Math.max(contractRules.minContract,Math.min(contractRules.maxContract,Math.round(p.salary*d.cap/150*1e6)/1e6));nextState.executiveSeason=executiveBaseline(nextState);}
nextState.news=[`Welcome to ${nextState.teams[0].city}, ${nextState.gmName}. Your owner has prepared your first-season priorities.`];return nextState}
